package kr.campusrent;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import static org.junit.jupiter.api.Assertions.*;import static kr.campusrent.RentalService.obj;
@SpringBootTest(properties={"debug=false","logging.level.root=WARN","logging.level.org.springframework=WARN","logging.level.com.zaxxer.hikari=WARN"}) @Transactional @EnabledIfSystemProperty(named="oracle.integration",matches="true")
class ResilienceOracleTest {
 @Autowired RentalService service;ObjectMapper json=new ObjectMapper();Map<String,Object> student=obj("id","2","role","student");
 JsonNode items(){String d=LocalDate.now(RentalService.KOREA).plusDays(18).toString();return json.valueToTree(Arrays.asList(obj("resourceId","E2","condition",obj("start",d+"T14:00","end",d+"T16:00"))));}
 @Test void retryReturnsSameRequestEvenAfterFirstResponseWasLost(){String key=UUID.randomUUID().toString();JsonNode items=items();List<String> first=service.submitOnce(items,key,student);assertEquals(first,service.submitOnce(items,key,student));((com.fasterxml.jackson.databind.node.ObjectNode)items.get(0).path("condition")).put("end",LocalDate.now(RentalService.KOREA).plusDays(18)+"T17:00");assertThrows(IllegalArgumentException.class,()->service.submitOnce(items,key,student));}
 @Test void paginationIsBoundedAndOwnerScoped(){for(int i=0;i<3;i++)service.submit(items(),student);Map<String,Object> a=service.state(student,0,2,"current"),b=service.state(student,1,2,"current");List<?> first=(List<?>)a.get("records"),second=(List<?>)b.get("records");assertEquals(2,first.size());assertFalse(first.toString().equals(second.toString()));for(Object r:first)assertEquals("2",((Map<?,?>)r).get("owner"));assertThrows(IllegalArgumentException.class,()->service.state(student,0,101,"all"));assertTrue(((List<?>)service.state(null,0,2,"all").get("records")).isEmpty());}
 @Test void passwordChangeStoresHashAndRequiresCurrentPassword(){String email="security-"+UUID.randomUUID()+"@campusrent.example";Map<String,Object> who=service.signup(json.valueToTree(obj("email",email,"name","보안 시험","password","InitialPassword123!")));service.changePassword(json.valueToTree(obj("currentPassword","InitialPassword123!","newPassword","ChangedPassword123!")),who);assertThrows(IllegalArgumentException.class,()->service.login(json.valueToTree(obj("email",email,"password","InitialPassword123!"))));assertNotNull(service.login(json.valueToTree(obj("email",email,"password","ChangedPassword123!"))));assertThrows(IllegalArgumentException.class,()->service.changePassword(json.valueToTree(obj("currentPassword","wrong","newPassword","AnotherPassword123!")),who));}
 @Test void productionBlocksSeedLogin(){RentalService target=org.springframework.test.util.AopTestUtils.getUltimateTargetObject(service);boolean old=target.blockDemo;try{target.blockDemo=true;assertFalse(service.demoAccountsEnabled());assertThrows(IllegalArgumentException.class,()->service.login(json.valueToTree(obj("email","admin@campusrent.example","password","CampusAdmin123!"))));}finally{target.blockDemo=old;}}
}
